using System;using System.Collections.Generic;using System.Reflection;using HalfAndHalf.Presentation;using NUnit.Framework;
namespace HalfAndHalf.Tests {
 public sealed class PlaneBinMapTests {
  const BindingFlags I=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
  static object Map(int capacity){var t=typeof(MeshSection).GetNestedType("PlaneBins",BindingFlags.NonPublic);Assert.That(t,Is.Not.Null,"Bound cap-point bin lookup to selection-owned storage without generic Dictionary dispatch");return Activator.CreateInstance(t,I,null,new object[]{capacity},null);}
  static int Get(object map,long key)=>(int)map.GetType().GetMethod("Get",I).Invoke(map,new object[]{key});
  static void Set(object map,long key,int value)=>map.GetType().GetMethod("Set",I).Invoke(map,new object[]{key,value});
  [Test] public void ExactLongKeysAndUpdatesSurviveCollidingBuckets(){var m=Map(64);var expected=new Dictionary<long,int>();for(int i=0;i<64;i++){long k=((long)i<<32)|(uint)i;Set(m,k,i);expected[k]=i;}foreach(var kv in expected)Assert.That(Get(m,kv.Key),Is.EqualTo(kv.Value));Set(m,0,97);Assert.That(Get(m,0),Is.EqualTo(97));Assert.That(Get(m,long.MinValue),Is.EqualTo(-1));Assert.That(Get(m,long.MaxValue),Is.EqualTo(-1));}
  [Test] public void ClearDropsOldEntriesAndAllowsTheFullCapacityAgain(){var m=Map(3);for(int pass=0;pass<100;pass++){for(int i=0;i<3;i++)Set(m,(long)pass*3+i,i);for(int i=0;i<3;i++)Assert.That(Get(m,(long)pass*3+i),Is.EqualTo(i));m.GetType().GetMethod("Clear",I).Invoke(m,null);for(int i=0;i<3;i++)Assert.That(Get(m,(long)pass*3+i),Is.EqualTo(-1));}}
  [Test] public void CapacityOverflowRefusesNewKeyAndPreservesAllExistingHeads(){var m=Map(2);Set(m,0,13);Set(m,long.MinValue,29);var e=Assert.Throws<TargetInvocationException>(()=>Set(m,17,41));Assert.That(e.InnerException,Is.TypeOf<InvalidOperationException>());Assert.That(Get(m,0),Is.EqualTo(13));Assert.That(Get(m,long.MinValue),Is.EqualTo(29));Set(m,0,53);Assert.That(Get(m,0),Is.EqualTo(53));}
  [Test] public void ReplacementReturnsThePreviousPlaneHeadIncludingIndexZero(){var m=Map(3);var replace=m.GetType().GetMethod("Replace",I);Assert.That(replace,Is.Not.Null);Assert.That((int)replace.Invoke(m,new object[]{17L,0}),Is.EqualTo(-1));Assert.That((int)replace.Invoke(m,new object[]{17L,2}),Is.EqualTo(0));Assert.That((int)replace.Invoke(m,new object[]{17L,1}),Is.EqualTo(2));Assert.That(Get(m,17),Is.EqualTo(1));m.GetType().GetMethod("Clear",I).Invoke(m,null);Assert.That((int)replace.Invoke(m,new object[]{17L,0}),Is.EqualTo(-1));}
  [Test] public void CollidingKeysResolveAcrossTheLastBucketAndAfterClear(){var m=Map(4);long[] keys={7L,14L,21L,28L,35L};for(int i=0;i<4;i++)Set(m,keys[i],i);for(int i=0;i<4;i++)Assert.That(Get(m,keys[i]),Is.EqualTo(i));Assert.That(Get(m,keys[4]),Is.EqualTo(-1));m.GetType().GetMethod("Clear",I).Invoke(m,null);Set(m,keys[4],3);for(int i=0;i<4;i++)Assert.That(Get(m,keys[i]),Is.EqualTo(-1));Assert.That(Get(m,keys[4]),Is.EqualTo(3));}
  [Test] public void ZeroCapacityStillAllowsClearAndMisses(){var m=Map(0);Assert.That(Get(m,0),Is.EqualTo(-1));m.GetType().GetMethod("Clear",I).Invoke(m,null);Assert.That(Get(m,-1),Is.EqualTo(-1));var e=Assert.Throws<TargetInvocationException>(()=>Set(m,0,0));Assert.That(e.InnerException,Is.TypeOf<InvalidOperationException>());}
 }
}
